async function waitForOutput(
  stream: Readable,
  expected: string,
  timeoutMs = HARNESS_STARTUP_TIMEOUT_MS,
): Promise<void> {
  await new Promise<void>((resolve, reject) => {
    let output = "";
    const signal = AbortSignal.timeout(timeoutMs);
    const cleanup = () => {
      stream.off("data", onData);
      stream.off("end", onEnd);
      signal.removeEventListener("abort", onAbort);
    };
    const onData = (chunk: Buffer) => {
      output += chunk.toString("utf8");
      if (output.includes(expected)) {
        cleanup();
        resolve();
      }
    };
    const onEnd = () => {
      cleanup();
      reject(new Error(`process exited before ${expected}: ${output}`));
    };
    const onAbort = () => {
      cleanup();
      reject(new Error(`process did not emit ${expected}: ${output}`));
    };
    stream.on("data", onData);
    stream.once("end", onEnd);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

async function waitForExit(child: ChildProcess, timeoutMs: number): Promise<boolean> {
  if (child.exitCode !== null || child.signalCode !== null) return true;
  const signal = AbortSignal.timeout(timeoutMs);
  try {
    await once(child, "exit", { signal });
    return true;
  } catch (error) {
    if (signal.aborted) return false;
    throw error;
  }
}

async function terminateProcessTree(child: ServiceProcess): Promise<void> {
  if (child.exitCode !== null || child.signalCode !== null) return;
  if (process.platform === "win32" && child.pid !== undefined) {
    const terminator = spawn("taskkill", ["/PID", String(child.pid), "/T", "/F"], {
      stdio: ["ignore", "ignore", "ignore"],
    });
    if (!(await waitForExit(terminator, HARNESS_SHUTDOWN_TIMEOUT_MS))) {
      terminator.kill();
      throw new Error(`taskkill timed out for process tree ${String(child.pid)}`);
    }
  } else {
    child.kill("SIGTERM");
  }
  if (!(await waitForExit(child, HARNESS_SHUTDOWN_TIMEOUT_MS))) {
    throw new Error(`process tree did not exit: ${String(child.pid)}`);
  }
}

async function start(
  command: readonly string[],
  expected: string,
  environment = process.env,
): Promise<ServiceProcess> {
  const executable = command[0];
  if (executable === undefined) throw new Error("empty process command");
  const child = spawn(executable, command.slice(1), {
    env: environment,
    stdio: ["ignore", "pipe", "pipe"],
  });
  try {
    await waitForOutput(child.stdout, expected);
    return child;
  } catch (error) {
    try {
      await terminateProcessTree(child);
    } catch (cleanupError) {
      console.error(
        "service startup cleanup failed:",
        new AggregateError([cleanupError], "service startup cleanup failed"),
      );
    }
    throw error;
  }
}

async function stop(child: ServiceProcess): Promise<void> {
  await terminateProcessTree(child);
}

