async function run(
  command: readonly string[],
  cwd?: string,
  environment = process.env,
): Promise<void> {
  const executable = command[0];
  if (executable === undefined) throw new Error("empty command");
  const child = spawn(executable, command.slice(1), {
    ...(cwd === undefined ? {} : { cwd }),
    env: environment,
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (!(await waitForExit(child, HARNESS_COMMAND_TIMEOUT_MS))) {
    await terminateProcessTree(child);
    throw new Error(`command timed out: ${command.join(" ")}`);
  }
  if (child.exitCode !== 0) {
    throw new Error(`command failed (${String(child.exitCode)}): ${command.join(" ")}`);
  }
}

