export type Environment = Readonly<Record<string, string | undefined>>;

declare const exactOriginBrand: unique symbol;
export type ExactOrigin = string & { readonly [exactOriginBrand]: true };

export interface ProjectionGatewayConfig {
  readonly host: string;
  readonly port: number;
  readonly allowedOrigin: ExactOrigin;
}

const DEFAULT_HOST = "0.0.0.0";
const DEFAULT_PORT = 3002;

function parsePort(value: string | undefined): number {
  if (value === undefined) {
    return DEFAULT_PORT;
  }

  const port = Number(value);
  if (!/^[1-9]\d{0,4}$/.test(value) || port > 65_535) {
    throw new Error("PROJECTION_GATEWAY_PORT must be an integer between 1 and 65535");
  }

  return port;
}

function parseExactOrigin(value: string | undefined): ExactOrigin {
  if (value === undefined || value.length === 0) {
    throw new Error("STAGE_ORIGIN is required");
  }

  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error("STAGE_ORIGIN must be an exact origin");
  }

  if ((parsed.protocol !== "http:" && parsed.protocol !== "https:") || parsed.origin !== value) {
    throw new Error("STAGE_ORIGIN must be an exact origin");
  }

  return value as ExactOrigin;
}

export function parseProjectionGatewayConfig(environment: Environment): ProjectionGatewayConfig {
  const host = environment.PROJECTION_GATEWAY_HOST ?? DEFAULT_HOST;
  if (host.length === 0) {
    throw new Error("PROJECTION_GATEWAY_HOST must not be empty");
  }
  if (/\s/.test(host)) {
    throw new Error("PROJECTION_GATEWAY_HOST must not contain whitespace");
  }

  return {
    host,
    port: parsePort(environment.PROJECTION_GATEWAY_PORT),
    allowedOrigin: parseExactOrigin(environment.STAGE_ORIGIN),
  };
}

import { describe, expect, test } from "bun:test";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { extname, join } from "node:path";

const browserRoots = ["apps/console", "apps/stage", "packages/ui"] as const;
const forbiddenImports = [
  "openai",
  "anthropic",
  "@google/generative-ai",
  "@aws-sdk/client-bedrock",
  "onnxruntime",
  "@tensorflow",
  "transformers",
  "langchain",
  "services/",
] as const;

function sourceFiles(root: string): string[] {
  const files: string[] = [];
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    if (entry.name === "dist" || entry.name === "node_modules") {
      continue;
    }
    const path = join(root, entry.name);
    if (entry.isDirectory()) {
      files.push(...sourceFiles(path));
    } else if ([".ts", ".tsx", ".js", ".jsx"].includes(extname(entry.name))) {
      files.push(path);
    }
  }
  return files;
}

function importSpecifiers(source: string): string[] {
  return [...source.matchAll(/(?:from\s+|import\s*\()["']([^"']+)["']/g)].flatMap((match) =>
    match[1] ? [match[1]] : [],
  );
}

function readManifest(app: "console" | "stage") {
  return JSON.parse(readFileSync(`apps/${app}/public/manifest.webmanifest`, "utf8")) as {
    id: string;
    name: string;
    display: string;
    scope: string;
    start_url: string;
  };
}

describe("browser build boundaries", () => {
  test("keeps browser import graphs free of services and model providers", () => {
    for (const root of browserRoots) {
      const manifest = readFileSync(`${root}/package.json`, "utf8").toLowerCase();
      for (const forbidden of forbiddenImports) {
        expect(manifest).not.toContain(forbidden);
      }

      for (const file of sourceFiles(root)) {
        for (const specifier of importSpecifiers(readFileSync(file, "utf8"))) {
          for (const forbidden of forbiddenImports) {
            expect(`${file}: ${specifier.toLowerCase()}`).not.toContain(forbidden);
          }
        }
      }
    }
  });

  test("ships independent PWA identities and service workers", () => {
    const consoleManifest = readManifest("console");
    const stageManifest = readManifest("stage");

    expect(consoleManifest.id).not.toBe(stageManifest.id);
    expect(consoleManifest.name).not.toBe(stageManifest.name);
    expect(consoleManifest.display).toBe("standalone");
    expect(stageManifest.display).toBe("fullscreen");
    expect(consoleManifest.scope).toBe("/");
    expect(stageManifest.scope).toBe("/");
    expect(consoleManifest.start_url).toBe("/");
    expect(stageManifest.start_url).toBe("/");

    const consoleConfig = readFileSync("apps/console/vite.config.ts", "utf8");
    const stageConfig = readFileSync("apps/stage/vite.config.ts", "utf8");
